	@Test
	void completedNotExistsTrainsOnlyTheSemiAntiSurface(@TempDir File dataDir) {
		LmdbStore store = initializedStore(dataDir);
		try {
			Filter filter = filter();
			LmdbEvaluationStatistics statistics = (LmdbEvaluationStatistics) store.getBackingStore()
					.getEvaluationStatistics();
			EvaluationStatistics.FilterPassEstimate ordinaryBefore = statistics.estimateFilterPass(filter);

			statistics.recordSemiAntiOutcome(filter, observation());

			EvaluationStatistics.FilterPassEstimate ordinaryAfter = statistics.estimateFilterPass(filter);
			assertEquals(ordinaryBefore.getSource(), ordinaryAfter.getSource());
			assertEquals(ordinaryBefore.getPassRatio(), ordinaryAfter.getPassRatio());
			LmdbOperatorFeedbackStats.SemiAntiEstimate estimate = statistics.estimatorRuntime()
					.semiAntiFeedback(filter, "NOT_EXISTS", "memoized-correlated");
			assertNotNull(estimate);
			assertEquals(1L, estimate.observationCount());
			assertEquals(4L, estimate.distinctKeys());
			assertEquals(2L, estimate.matchedKeys());
			assertEquals(2L, estimate.unmatchedKeys());
			assertEquals(6L, estimate.repeatedOuterRows());
			assertEquals(18L, estimate.rhsRowsExamined());
			assertEquals(4L, estimate.exhaustedFailures());
			assertEquals(4L, estimate.iteratorOpens());
			assertEquals(10L, estimate.cacheLookups());
		} finally {
			store.shutDown();
		}
	}

